function formatCurrency(amount: number, opts?: { compact?: boolean }): string {
  if (opts?.compact && amount >= 1000) {
    return `$${(amount / 1000).toFixed(amount % 1000 === 0 ? 0 : 1)}k`;
  }
  return amount.toLocaleString('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  });
}

// Structured data for search engines / AI summaries. Three schemas wired into
// one graph: Organization (brand), WebSite (sitelinks search), and FAQPage
