function StructuredData(): React.ReactElement {
  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? 'https://carrieraudit.com';
  const base = appUrl.replace(/\/$/, '');
  const graph = {
    '@context': 'https://schema.org',
    '@graph': [
      {
        '@type': 'Organization',
        '@id': `${base}#org`,
        name: 'CarrierAudit',
        url: base,
        logo: `${base}/icon`,
        description:
          "We audit business wireless bills for Verizon, AT&T, and T-Mobile. Find the 18-32% you're overpaying in under 5 minutes.",
      },
      {
        '@type': 'WebSite',
        '@id': `${base}#site`,
        url: base,
        name: 'CarrierAudit',
        publisher: { '@id': `${base}#org` },
      },
      {
        '@type': 'FAQPage',
        mainEntity: FAQ_ITEMS.map((item) => ({
          '@type': 'Question',
          name: item.q,
          acceptedAnswer: {
            '@type': 'Answer',
            text: item.a,
          },
        })),
      },
    ],
  };
  return (
    <script
      type="application/ld+json"
      // JSON.stringify on a constant object — no XSS surface.
      dangerouslySetInnerHTML={{ __html: JSON.stringify(graph) }}
    />
  );
}

